 ICON.cmBars=(x,y)=>{const k=1.15,bar=(yy,parts)=>{let xx=10,s='';parts.forEach(([v,col])=>{s+=CM_R(xx,yy,Math.max(4,v*k),56,col,.85);xx+=Math.max(4,v*k)});return s};return `<g transform="translate(${x-210} ${y-165})">${CM_T(10,40,'cable first: 313.0 K',{fs:24,fw:800,fill:ORG})}${bar(56,[[169.6,GRN],[119.0,BLU],[24.4,ORG]])}${CM_T(10,176,'LNA first: 101.2 K',{fs:24,fw:800,fill:GRN})}${bar(192,[[75.1,BLU],[1.7,GRN],[24.4,ORG]])}${CM_T(10,300,'green cable, blue LNA, orange mixer',{fs:20,fill:CM_MUT})}</g>`};
